const columnCount = 144
const rowCount = 73
const gridStep = 2.5

function clamp(value: number, minimum: number, maximum: number) {
  return Math.max(minimum, Math.min(maximum, value))
}

export function sampleNcepSlp(month: NcepSlpMonth, longitude: number, latitude: number) {
  const values = month === 'january' ? januaryTenthsHpa : julyTenthsHpa
  const normalizedLongitude = ((longitude % 360) + 360) % 360
  const x = normalizedLongitude / gridStep
  const x0 = Math.floor(x) % columnCount
  const x1 = (x0 + 1) % columnCount
  const tx = x - Math.floor(x)
  const y = clamp((90 - latitude) / gridStep, 0, rowCount - 1)
  const y0 = Math.floor(y)
  const y1 = Math.min(rowCount - 1, y0 + 1)
  const ty = y - y0
  const top = values[y0 * columnCount + x0]! * (1 - tx) + values[y0 * columnCount + x1]! * tx
  const bottom = values[y1 * columnCount + x0]! * (1 - tx) + values[y1 * columnCount + x1]! * tx
  return (top * (1 - ty) + bottom * ty) / 10
}
